'use strict';
const assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path'),{createHash}=require('node:crypto');
function createGetChainEvidence({identity,progress,student,root,model,state,judgments}){
 let protectedVictim,immutable;const hash=s=>createHash('sha256').update(s).digest('hex');
 const save=(name,value)=>fs.writeFileSync(path.join(root,name+'.json'),JSON.stringify(value,null,2),{mode:0o600});
 async function packetFor(id){const rows=(await judgments()).filter(j=>j.objective_id===id&&j.verdict==='pass');assert.equal(rows.length,1);const j=rows[0];assert.equal(j.disposition,'awarded');assert.equal(j.result_json.provider,'ollama');assert.equal(j.result_json.model,model);assert.ok(j.result_json.attempts>=1);const raw=(await identity.query('SELECT packet FROM workshop_platform.grade_packets WHERE user_id=$1 AND evaluation_id=$2',[student.id,j.evaluation_id])).rows[0].packet;assert.equal(hash(raw),j.evidence_digest);const packet=JSON.parse(raw);assert.equal(packet.facts.required_observation,true);save('csrf-chain-packet-'+id,packet);return{j,packet};}
 return async(stage,details)=>{
  if(stage==='recon-1'){assert.equal((await state(student)).get.reconCount,1);assert.equal((await progress.getWorkshopProgress(student.id,'csrf_workshop')).completedObjectiveCount,0);assert.equal((await judgments()).filter(j=>j.disposition==='awarded').length,0);}
  if(stage==='recon-2'){
   assert.equal((await state(student)).get.reconCount,2);const {j,packet}=await packetFor('csrf_g1');assert.equal(packet.rubric.version,'csrf-recon-v9');assert.equal(packet.facts.actual_recon_history,true);const proof=packet.evidence.find(e=>e.id==='recon_history').content;assert.equal(proof.currentRunId,j.run_id);assert.equal(proof.ownerKey,JSON.stringify(['CSRF',String(student.id)]));assert.equal(proof.runs.length,2);assert.ok(require('../../server/services/csrfReconProof').validProof(proof,{ownerKey:JSON.stringify(['CSRF',String(student.id)]),runId:j.run_id}));
   const traces=[];for(const run of proof.runs){const rows=(await identity.query('SELECT sequence,node,event_type,metadata FROM graph_runtime.events WHERE run_id=$1 AND owner_key=$2 ORDER BY sequence',[run.runId,proof.ownerKey])).rows;const decision=rows.find(e=>e.sequence===run.decisionSeq);assert.equal(decision.node,'classify');assert.equal(decision.metadata.decisionSource,'model');assert.equal(decision.metadata.tool,'recon');assert.equal(decision.metadata.provider,'ollama');assert.equal(decision.metadata.model,model);assert.equal(rows.find(e=>e.sequence===run.effectSeq).node,'csrf_recon_get');assert.equal(rows.find(e=>e.sequence===run.endSeq).event_type,'node_end');traces.push({runId:run.runId,events:rows});}assert.equal(new Set(traces.map(t=>t.runId)).size,2);save('csrf-chain-recon-traces',traces);
  }
  if(stage==='effect'||stage==='defense-effect'){
   const id=stage==='effect'?'csrf_g2':'csrf_g3',{j,packet}=await packetFor(id),receipt=packet.evidence.find(e=>e.id==='receipt').content,action=packet.evidence.find(e=>e.id==='action').content;
   assert.equal(receipt.runId,j.run_id);assert.equal(receipt.ownerKey,JSON.stringify(['CSRF',String(student.id)]));assert.equal(receipt.objectiveId,id);assert.equal(receipt.payloadDigest,hash(details.html));assert.equal(receipt.cookiePresent,true);assert.equal(receipt.responseObserved,true);assert.equal(action.result.vector,'direct_get');
   if(id==='csrf_g2'){assert.equal(action.result.stateChanged,true);assert.equal((await state(student)).get.victim.profile.email,'managed-owned@fixture.invalid');const events=(await identity.query('SELECT node,event_type,metadata FROM graph_runtime.events WHERE run_id=$1 ORDER BY sequence',[j.run_id])).rows;assert(events.some(e=>e.node==='classify'&&e.metadata?.decisionSource==='model'&&e.metadata?.tool==='change_email'&&e.metadata?.provider==='ollama'&&e.metadata?.model===model));save('csrf-chain-g2-traces',events);}
   else{assert.equal(packet.rubric.version,'csrf-defense-mode-v10');assert.equal(packet.rubric.mode,'vuln');assert.equal(j.result_json.rubricVersion,'csrf-defense-mode-v10');assert.equal(j.result_json.mode,'vuln');assert.equal(receipt.responseStatus,403);assert.equal(action.result.blocked,true);assert.equal(action.result.defenses.csrfToken,true);assert.deepEqual((await state(student)).get.victim,protectedVictim);immutable=await judgments();save('csrf-chain-canonical-judgments',immutable);assert.deepEqual(immutable.filter(j=>j.disposition==='awarded').map(j=>j.objective_id).sort(),['csrf_g1','csrf_g2','csrf_g3']);}
   assert.equal((await progress.getWorkshopProgress(student.id,'csrf_workshop')).completedObjectiveCount,id==='csrf_g2'?2:3);
  }
  if(stage==='defense-enabled'){const current=await state(student);assert.equal(current.get.defenses.csrfToken,true);protectedVictim=structuredClone(current.get.victim);}
  if(stage==='reset'){assert.equal((await progress.getWorkshopProgress(student.id,'csrf_workshop')).completedObjectiveCount,0);assert.deepEqual(await judgments(),immutable);assert.notEqual((await state(student)).get.victim.profile.email,'managed-owned@fixture.invalid');}
 };
}
module.exports={createGetChainEvidence};
